// The published week's ranking snapshot.
//
// Written by the weekly build (see CLAUDE-RANKINGS.md). Every number here came
// from a live fetch; nothing in this file is written by hand or recalled from
// memory. `asOf` on a source is the date the SOURCE reports and is what the
// 30-day age gate in lib/gridiron.js reads.
//
// Shape (v2, 2026-09-01): { fetchedAt, season, <sport>: { sport, week, gamesAt,
// linesAt, sources, games, lines } }.
//   week    the ESPN week whose games are NEXT (so week-1 games are complete)
//   games   every completed game this season: { w, id, d, hid, aid, n, hs, as,
//           hy, ay, hto, ato } (n = 1 on a neutral field; ids are ESPN team ids;
//           hy/ay total yards and hto/ato turnovers from the ESPN summary
//           endpoint, `boxscore.teams[].statistics` totalYards / turnovers;
//           a game without them falls back to its raw margin)
//   lines   one closing or current point spread per game, home-team spread,
//           for the current week and the two before it: { w, id, hid, aid, n, sp }
//   sources only 'market' and 'model' tiers are scored; there are no media or
//           poll sources in the composite (owner rule, 2026-09-01)
//
// MLB differs in three fields, because baseball is priced and measured
// differently (CLAUDE-RANKINGS.md section 2e):
//   games   carry `hbr`/`abr`, the BaseRuns runs each side's own batting line
//           implied in that game, in place of football's `hy`/`ay` yards.
//           They feed the unscored Luck column, NOT the margin.
//   lines   carry `hml`/`aml`, the closing MONEYLINE for each side, in place
//           of `sp`. Baseball's runline is fixed at 1.5 with the price doing
//           the work, so it is not a spread and is not stored.
//   brK     the BaseRuns B-multiplier fit to this season's run environment.
//
//
// CFB, 2026-09-08: week 1 is complete -- 99 FBS games from Aug 29 through the
// SMU at Florida State Monday nighter on Sep 7 -- so `week` is 2 and the
// results pillar opens at 0.40 * 1/6. Every game carries its box score and its
// closing spread; the 53 week-2 lines are current, not closed. ESPN's provider
// list carries no id 58 right now, so the spreads are DraftKings (id 100).
//
// The four model columns are stored at their PUBLISHED depth, 138 each, not the
// top 50 they used to be truncated to. That is the open item in
// CLAUDE-RANKINGS.md section 2d: below the stored depth every team took a
// model's tail mean and the MODELS column then printed an order no model had
// produced. Nothing on the board reads `off board` now.
//
// Sagarin is the PREDICTOR column from here on. The word STARTING has left the
// page -- it now reads "through results of SEPTEMBER 7 MONDAY - WEEK 1" -- so
// PREDICTOR has separated from RATING, and RATING in season is a pure results
// model that pillar R already computes (section 2, pillar A).
//
// F+ still publishes its preseason board and says so in its own heading,
// "2026 F+ Ratings (through Week 0)", so it is dated as what it is rather than
// as the day it was pulled. DRatings prints "Updated 8 days ago" over a board
// carrying week-1 records, hence 2026-08-31.
//
// The futures board carries ALL 138 FBS teams and it RE-PRICED this week (Ohio
// State +550 against +600 on the 08-28 board it was frozen at), so it is dated
// 2026-09-08. Below rank 50 it is the only market signal a team without a line
// has. Never truncate it to the display depth; see CLAUDE-RANKINGS.md 2d.
//
// NFL, 2026-09-11: week 1 is UNDERWAY, not complete. Two of its sixteen games
// are final -- New England at Seattle on Wednesday and San Francisco against
// the Rams at the Melbourne Cricket Ground on Thursday -- and both are stored
// with their box scores and their DraftKings closing numbers. `week` therefore
// stays 1, because week 1 is still the week whose games are next, so
// `weeksPlayed` is 0 and the results ramp is 0: these two results show in the
// Résumé column and in the "played since this board was priced" note without
// moving a rating. They begin to score when the Monday nighter finishes week 1
// and `week` advances to 2.
//
// All 32 week-1 and week-2 spreads were re-pulled in the same gather and 13 of
// them moved off the 09-04 numbers, which is the proof they are live prices and
// not a re-served snapshot. ESPN's provider list still carries no id 58, so
// these are DraftKings (id 100), same as CFB.
//
// NFL sources, same day, refreshed on an owner call after the Rams held rank 1
// off a board priced entirely before kickoff. FOUR of the six republished:
//   fpi        2026-09-11T17:31Z. Value order and `fpirank` order agree exactly,
//              checked both ways, because the column it produces is startling:
//              SEATTLE 3 -> 18 AFTER WINNING. FPI is efficiency-weighted and 285
//              yards in a 3-point win prices badly. Largest move 15, at the §5
//              limit, not over it. Rams 1 -> 4.
//   vegas      "Odds as of September 11, 2026", 5 books, and the Rams are STILL
//              the Super Bowl favourite at a +600 median against Buffalo +1000.
//              The books did not move them. Largest move 5.
//   kalshi     "Updated Friday, Sep 11, 2026 · 4:36 PM ET", the one source that
//              repriced hard: Rams 1 -> 17, 49ers 13 -> 1, Patriots 10 -> 22.
//              ⚠️ That Rams move is SIXTEEN spots and trips §5 gate rule 6,
//              which caps a week-over-week move at fifteen. It is published
//              anyway, deliberately: the rule exists to catch a silently broken
//              parser, and this column is 32 deep, every name resolves, it
//              carries today's own timestamp, and its three big movers are
//              exactly the three teams that played. A live prediction market
//              moving 16 spots on a 27-7 upset is the source working. The rule
//              wants scoping to week-over-week comparisons rather than an
//              intra-week refresh; §8 carries it as an open item.
//   wintotals  re-read, largest move 2, still undated and still carrying its own
//              content-derived 2026 season signal.
// The two that did NOT republish are left byte-identical rather than restamped:
// Sagarin still prints "2026 STARTING RATINGS" (it updates Tuesdays) and
// DRatings still says "Updated 46 days ago" over a 0-0 board, so it stays out at
// 46 days against the 30-day limit, as it was.
//
// ⚠️ `builtAt` on the NFL block is NEW and is what makes a one-sport refresh
// honest. `fetchedAt` is file-level: leaving it at 09-08 would date these
// 09-11 sources three days into the FUTURE and render "-3 days old" under a
// gate that only tests `age > 30`; moving it to 09-11 would stamp the untouched
// CFB and MLB boards as built today. So NFL carries its own build date, CFB and
// MLB still fall back to `fetchedAt`, and verify-gridiron.mjs check 9 now fails
// any source dated after the block it sits in.
